import{_ as t,o as a,c as o,a2 as r}from"./chunks/framework.CAKCj7G0.js";const _=JSON.parse('{"title":"路由组件","description":"","frontmatter":{},"headers":[],"relativePath":"DuOneClass/09.react/5-1.路由组件.md","filePath":"DuOneClass/09.react/5-1.路由组件.md"}'),i={name:"DuOneClass/09.react/5-1.路由组件.md"};function l(c,e,n,s,h,u){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="路由组件" tabindex="-1">路由组件 <a class="header-anchor" href="#路由组件" aria-label="Permalink to &quot;路由组件&quot;">​</a></h1><p>React-Router 为我们提供了两个重要组件</p><h2 id="router组件" tabindex="-1">Router组件 <a class="header-anchor" href="#router组件" aria-label="Permalink to &quot;Router组件&quot;">​</a></h2><p>它本身不做任何展示，仅提供路由模式配置，另外，该组件会产生一个上下文，上下文中会提供一些实用的对象和方法，供其他相关组件使用</p><ol><li>HashRouter：该组件，使用hash模式匹配</li><li>BrowserRouter：该组件，使用BrowserHistory模式匹配</li></ol><p>通常情况下，Router组件只有一个，将该组件包裹整个页面</p><h2 id="route组件" tabindex="-1">Route组件 <a class="header-anchor" href="#route组件" aria-label="Permalink to &quot;Route组件&quot;">​</a></h2><p>根据不同的地址，展示不同的组件</p><p>重要属性：</p><ol><li>path：匹配的路径 <ol><li>默认情况下，不区分大小写，可以设置sensitive属性为true，来区分大小写</li><li>默认情况下，只匹配初始目录，如果要精确匹配，配置exact属性为true</li><li>如果不写path，则会匹配任意路径</li></ol></li><li>component：匹配成功后要显示的组件</li><li>children： <ol><li>传递React元素，无论是否匹配，一定会显示children，并且会忽略component属性</li><li>传递一个函数，该函数有多个参数，这些参数来自于上下文，该函数返回react元素，则一定会显示返回的元素，并且忽略component属性</li></ol></li></ol><p>Route组件可以写到任意的地方，只要保证它是Router组件的后代元素</p><h2 id="switch组件" tabindex="-1">Switch组件 <a class="header-anchor" href="#switch组件" aria-label="Permalink to &quot;Switch组件&quot;">​</a></h2><p>写到Switch组件中的Route组件，当匹配到第一个Route后，会立即停止匹配</p><p>由于Switch组件会循环所有子元素，然后让每个子元素去完成匹配，若匹配到，则渲染对应的组件，然后停止循环。因此，不能在Switch的子元素中使用除Route外的其他组件。</p>',14)])])}const d=t(i,[["render",l]]);export{_ as __pageData,d as default};
